import { StyleFn } from "..";

export const Backdrop: StyleFn = (theme, mode) => {
  const { color } = theme;
  return {
    root: {
      zIndex: -1,
      position: "fixed",
      right: 0,
      bottom: 0,
      top: 0,
      left: 0,
      backgroundColor: color.palette.transparent.blue[40],
      WebkitTapHighlightColor: "transparent",
    },
  }
};